          <label class="svhl">${esc(L({ ja:'確認方法', en:'Method', vi:'Cách kiểm tra' }))}<select id="sv_method">${SV_METHODS.map(([k, l]) => `<option value="${k}"${(m.method || 'onsite') === k ? ' selected' : ''}>${esc(L(l))}</option>`).join('')}</select></label>
